const VF = struct {
    np: usize, // tap pairs (odd tap count padded with a zero-weight row)
    rows: [2 * MAXP][*]const i16,
    cps: [MAXP]@Vector(16, i16),

    inline fn init(rows: []const [*]const i16, f: []const i16) VF {
        var v: VF = undefined;
        v.np = (rows.len + 1) / 2;
        for (0..v.np) |p| {
            const j = 2 * p;
            v.rows[j] = rows[j];
            if (j + 1 < rows.len) {
                v.rows[j + 1] = rows[j + 1];
                v.cps[p] = pairCoef(f[j], f[j + 1]);
            } else {
                v.rows[j + 1] = rows[j];
                v.cps[p] = pairCoef(f[j], 0);
            }
        }
        return v;
    }

    /// sum_j rows[j][i..i+16] * f[j] (exact i32), two taps per pmaddwd.
    inline fn f16(v: *const VF, i: usize) VI32 {
        var lo: @Vector(8, i32) = @splat(0);
        var hi: @Vector(8, i32) = @splat(0);
        for (0..v.np) |p| {
            const a: @Vector(16, i16) = v.rows[2 * p][i..][0..16].*;
            const b: @Vector(16, i16) = v.rows[2 * p + 1][i..][0..16].*;
            lo += madd(@shuffle(i16, a, b, unpLo()), v.cps[p]);
            hi += madd(@shuffle(i16, a, b, unpHi()), v.cps[p]);
        }
        return @shuffle(i32, lo, hi, fixOrder());
    }

    /// 8-lane variant for half-width chroma.
    inline fn f8(v: *const VF, i: usize) @Vector(8, i32) {
        var acc: @Vector(8, i32) = @splat(0);
