inline fn spl(x: u32) @Vector(16, i16) {
    return @bitCast(@as(@Vector(8, u32), @splat(x)));
}

const Pairs = struct { rg_lo: @Vector(16, i16), rg_hi: @Vector(16, i16), bg_lo: @Vector(16, i16), bg_hi: @Vector(16, i16) };

inline fn mkPairs(c: [3]@Vector(N, i16)) Pairs {
    return .{
        .rg_lo = @shuffle(i16, c[0], c[1], unpLo()),
        .rg_hi = @shuffle(i16, c[0], c[1], unpHi()),
        .bg_lo = @shuffle(i16, c[2], c[1], unpLo()),
        .bg_hi = @shuffle(i16, c[2], c[1], unpHi()),
    };
}

inline fn pmDot(c: Pairs, rg: u32, bg: u32) VI32 {
    const a = spl(rg);
    const b = spl(bg);
    const lo = madd(c.rg_lo, a) + madd(c.bg_lo, b);
    const hi = madd(c.rg_hi, a) + madd(c.bg_hi, b);
    return @shuffle(i32, lo, hi, fixOrderIn());
}

fn fixOrderIn() @Vector(16, i32) {
    var m: [16]i32 = undefined;
    for (0..4) |q| {
        m[q] = @intCast(q);
        m[4 + q] = ~@as(i32, @intCast(q));
        m[8 + q] = @intCast(4 + q);
        m[12 + q] = ~@as(i32, @intCast(4 + q));
    }
    return m;
}

